/** Read the owner-linked public virtual-tour scene metadata; no site changes. */
import {createRequire} from 'node:module';import {writeFile,mkdir} from 'node:fs/promises';import {browserExecutable} from '../landmark-preflight/browser-runtime.mjs';
const root=new URL('../../../',import.meta.url),require=createRequire(new URL('3d-viewer/city/package.json',root)),{chromium}=require('playwright'),out=new URL('docs/astra-city/government-import/government-xl-two-harbourfront-primary-owner-20261009/',root);await mkdir(out,{recursive:true});const browser=await chromium.launch({headless:true,executablePath:browserExecutable(chromium),args:['--no-sandbox','--enable-webgl']});
try {const page=await browser.newPage({viewport:{width:1600,height:1000}}),requests=[],errors=[];page.on('response',r=>requests.push({url:r.url(),status:r.status()}));page.on('pageerror',e=>errors.push(e.message));await page.goto('https://www.harbourfront.hk/',{waitUntil:'domcontentloaded',timeout:60000});await page.waitForFunction(()=>{const k=document.getElementById('krpanoSWFObject');return k&&typeof k.get==='function'&&k.get('scene.count')>0},{timeout:60000});
 await page.waitForLoadState('networkidle',{timeout:45000});
 const data=await page.evaluate(()=>{const k=document.getElementById('krpanoSWFObject'),n=k.get('scene.count'),scenes=[];for(let i=0;i<n;i++){let s={};for(const p of ['name','title','thumburl','lat','lng','alt','heading'])s[p]=k.get('scene['+i+'].'+p);scenes.push(s);}return {scenes,currentScene:k.get('xml.scene'),currentImage:{cube:k.get('image.cube.url'),preview:k.get('preview.url'),sphere:k.get('image.sphere.url')},currentView:{hlookat:k.get('view.hlookat'),vlookat:k.get('view.vlookat'),fov:k.get('view.fov')}};});await page.screenshot({path:new URL('owner-tour-initial.png',out).pathname});await writeFile(new URL('owner-tour-scenes.json',out),JSON.stringify({sourceURL:'https://www.harbourfront.hk/',...data,requests,errors,siteChanged:false,qualified:'Read-only public owner-authored runtime scene metadata, primary photographic evidence awaiting independent geometric registration.'},null,2));console.log(JSON.stringify(data));}finally{await browser.close();}
